  /**
   * @method
   * @name bydfi#fetchMarkets
   * @description retrieves data on all markets for bydfi
   * @see
   * https://developers.bydfi.com/en/futures/market#fetching-trading-rules-and-pairs
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object[]} an array of objects representing market data
   */
  std::shared_future<ccxt::any>
  fetchMarkets(ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        ccxt::any response = awaitValue(
                            this->publicGetV1FapiMarketExchangeInfo(params));
                        //
                        //     {
                        //         "code": "200",
                        //         "message": "success",
                        //         "data": [
                        //             {
                        //                 "symbol": "CLANKER-USDT",
                        //                 "baseAsset": "CLANKER",
                        //                 "marginAsset": "USDT",
                        //                 "quoteAsset": "USDT",
                        //                 "contractFactor": "0.01",
                        //                 "limitMaxQty": "50000",
                        //                 "limitMinQty": "1",
                        //                 "marketMaxQty": "10000",
                        //                 "marketMinQty": "1",
                        //                 "pricePrecision": "8",
                        //                 "basePrecision": "8",
                        //                 "feeRateTaker": "0.0006",
                        //                 "feeRateMaker": "0.0002",
                        //                 "liqFeeRate": "0.0006",
                        //                 "openBuyLimitRateMax": "0.05",
                        //                 "openSellLimitRateMax": "100",
                        //                 "openBuyLimitRateMin": "0.98",
                        //                 "openSellLimitRateMin": "0.05",
                        //                 "priceOrderPrecision": "2",
                        //                 "baseShowPrecision": "2",
                        //                 "maxLeverageLevel": "20",
                        //                 "volumePrecision": "2",
                        //                 "maxLimitOrderNum": "200",
                        //                 "maxPlanOrderNum": "10",
                        //                 "reverse": false,
                        //                 "onboardTime": "1763373600000",
                        //                 "status": "NORMAL"
                        //             },
                        //             ...
                        //         ],
                        //         "success": true
                        //     }
                        ccxt::any data = this->safeList(
                            response, std::string("data"), ccxt::list{});
                        return this->parseMarkets(data);
                      })
        .share();
  }

  ccxt::any parseMarket(ccxt::any market) override {
    //
    //     {
    //         "symbol": "CLANKER-USDT",
    //         "baseAsset": "CLANKER",
    //         "marginAsset": "USDT",
    //         "quoteAsset": "USDT",
    //         "contractFactor": "0.01",
    //         "limitMaxQty": "50000",
    //         "limitMinQty": "1",
    //         "marketMaxQty": "10000",
    //         "marketMinQty": "1",
    //         "pricePrecision": "8",
    //         "basePrecision": "8",
    //         "feeRateTaker": "0.0006",
    //         "feeRateMaker": "0.0002",
    //         "liqFeeRate": "0.0006",
    //         "openBuyLimitRateMax": "0.05",
    //         "openSellLimitRateMax": "100",
    //         "openBuyLimitRateMin": "0.98",
    //         "openSellLimitRateMin": "0.05",
    //         "priceOrderPrecision": "2",
    //         "baseShowPrecision": "2",
    //         "maxLeverageLevel": "20",
    //         "volumePrecision": "2",
    //         "maxLimitOrderNum": "200",
    //         "maxPlanOrderNum": "10",
    //         "reverse": false,
    //         "onboardTime": "1763373600000",
    //         "status": "NORMAL"
    //     }
    //
    ccxt::any id = this->safeString(market, std::string("symbol"));
    ccxt::any baseId = this->safeString(market, std::string("baseAsset"));
    ccxt::any quoteId = this->safeString(market, std::string("quoteAsset"));
    ccxt::any settleId = this->safeString(market, std::string("marginAsset"));
    ccxt::any base = this->safeCurrencyCode(baseId);
    ccxt::any quote = this->safeCurrencyCode(quoteId);
    ccxt::any settle = this->safeCurrencyCode(settleId);
    ccxt::any symbol = add(
        add(add(add(base, std::string("/")), quote), std::string(":")), settle);
    ccxt::any inverse = this->safeBool(market, std::string("reverse"));
    ccxt::any limitMaxQty =
        this->safeString(market, std::string("limitMaxQty"));
    ccxt::any marketMaxQty =
        this->safeString(market, std::string("marketMaxQty"));
    ccxt::any maxAmountString =
        ccxt::Precise::stringMax(limitMaxQty, marketMaxQty);
    ccxt::any marketMinQty =
        this->safeString(market, std::string("marketMinQty"));
    ccxt::any limitMinQty =
        this->safeString(market, std::string("limitMinQty"));
    ccxt::any minAmountString =
        ccxt::Precise::stringMin(marketMinQty, limitMinQty);
    ccxt::any contractSize =
        this->safeString(market, std::string("contractFactor"));
    ccxt::any pricePrecision = this->parsePrecision(
        this->safeString(market, std::string("priceOrderPrecision")));
    ccxt::any rawAmountPrecision = this->parsePrecision(
        this->safeString(market, std::string("volumePrecision")));
    ccxt::any amountPrecision =
        ccxt::Precise::stringDiv(rawAmountPrecision, contractSize);
    ccxt::any basePrecision = this->parsePrecision(
        this->safeString(market, std::string("basePrecision")));
    ccxt::any taker = this->safeNumber(market, std::string("feeRateTaker"));
    ccxt::any maker = this->safeNumber(market, std::string("feeRateMaker"));
    ccxt::any maxLeverage =
        this->safeNumber(market, std::string("maxLeverageLevel"));
    ccxt::any status = this->safeString(market, std::string("status"));
    return this->safeMarketStructure(ccxt::dict{
        {std::string("id"), id},
        {std::string("symbol"), symbol},
        {std::string("base"), base},
        {std::string("quote"), quote},
        {std::string("settle"), settle},
        {std::string("baseId"), baseId},
        {std::string("quoteId"), quoteId},
        {std::string("settleId"), settleId},
        {std::string("type"), std::string("swap")},
        {std::string("spot"), false},
        {std::string("margin"), ccxt::any{}},
        {std::string("swap"), true},
        {std::string("future"), false},
        {std::string("option"), false},
        {std::string("active"), isEqual(status, std::string("NORMAL"))},
        {std::string("contract"), true},
        {std::string("linear"), !isEqual(inverse, true)},
        {std::string("inverse"), inverse},
        {std::string("taker"), taker},
        {std::string("maker"), maker},
        {std::string("contractSize"), this->parseNumber(contractSize)},
        {std::string("expiry"), ccxt::any{}},
        {std::string("expiryDatetime"), ccxt::any{}},
        {std::string("strike"), ccxt::any{}},
        {std::string("optionType"), ccxt::any{}},
        {std::string("precision"),
         ccxt::dict{
             {std::string("amount"), this->parseNumber(amountPrecision)},
             {std::string("price"), this->parseNumber(pricePrecision)},
             {std::string("base"), this->parseNumber(basePrecision)},
         }},
        {std::string("limits"),
         ccxt::dict{
             {std::string("leverage"),
              ccxt::dict{
                  {std::string("min"), ccxt::any{}},
                  {std::string("max"), maxLeverage},
              }},
             {std::string("amount"),
              ccxt::dict{
                  {std::string("min"), this->parseNumber(minAmountString)},
                  {std::string("max"), this->parseNumber(maxAmountString)},
              }},
             {std::string("price"),
              ccxt::dict{
                  {std::string("min"), ccxt::any{}},
                  {std::string("max"), ccxt::any{}},
              }},
             {std::string("cost"),
              ccxt::dict{
                  {std::string("min"), ccxt::any{}},
                  {std::string("max"), ccxt::any{}},
              }},
         }},
        {std::string("created"),
         this->parse8601(this->safeString(market, std::string("createdAt")))},
        {std::string("info"), market},
    });
  }

  /**
   * @method
   * @name bydfi#fetchOrderBook
   * @description fetches information on open orders with bid (buy) and ask
   * (sell) prices, volumes and other data
   * @see https://developers.bydfi.com/en/futures/market#depth-information
   * @param {string} symbol unified symbol of the market to fetch the order book
   * for
   * @param {int} [limit] the maximum amount of order book entries to return,
   * could be 5, 10, 20, 50, 100, 500 or 1000 (default 500)
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.loc] crypto location, default: us
   * @returns {object} an [order book structure]{@link
   * https://docs.ccxt.com/?id=order-book-structure}
   */
  std::shared_future<ccxt::any>
  fetchOrderBook(ccxt::any symbol, ccxt::any limit = ccxt::any{},
                 ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        ccxt::any market = this->market(symbol);
                        ccxt::any request = ccxt::dict{
                            {std::string("symbol"),
                             ::getValue(market, std::string("id"))},
                        };
                        if (isTrue(!isEqual(limit, ccxt::any{}))) {
                          ::setValue(request, std::string("limit"),
                                     this->getClosestLimit(limit));
                        }
                        ccxt::any response =
                            awaitValue(this->publicGetV1FapiMarketDepth(
                                this->extend(request, params)));
                        //
                        //     {
                        //         "code": 200,
                        //         "message": "success",
                        //         "data": {
                        //             "lastUpdateId": "221780076",
                        //             "symbol": "ETH-USDT",
                        //             "asks": [
                        //                 {
                        //                     "price": "2958.21",
                        //                     "amount": "39478"
                        //                 },
                        //                 ...
                        //             ],
                        //             "bids": [
                        //                 {
                        //                     "price": "2958.19",
                        //                     "amount": "174498"
                        //                 },
                        //                 ...
                        //             ],
                        //             "e": "221780076"
                        //         },
                        //         "success": true
                        //     }
                        //
                        ccxt::any data = this->safeDict(
                            response, std::string("data"), ccxt::dict{});
                        ccxt::any timestamp = this->milliseconds();
                        ccxt::any orderBook = this->parseOrderBook(
                            data, ::getValue(market, std::string("symbol")),
                            timestamp, std::string("bids"), std::string("asks"),
                            std::string("price"), std::string("amount"));
                        ::setValue(orderBook, std::string("nonce"),
                                   this->safeInteger(
                                       data, std::string("lastUpdateId")));
                        return orderBook;
                      })
        .share();
  }

  virtual ccxt::any getClosestLimit(ccxt::any limit) {
    ccxt::any limits = ccxt::list{5, 10, 20, 50, 100, 500, 1000};
    ccxt::any result = 1000;
    for (ccxt::any i = 0; isLessThan(i, getArrayLength(limits));
         postFixIncrement(i)) {
      if (isTrue(isEqual(limit, ccxt::any{}))) {
        throw ArgumentsRequired(toString(
            add(this->id,
                std::string(" getClosestLimit() requires a limit argument"))));
      }
      if (isTrue(isLessThanOrEqual(limit, ::getValue(limits, i)))) {
        result = ::getValue(limits, i);
        break;
      }
    }
    return result;
  }

  /**
   * @method
   * @name bydfi#fetchTrades
   * @description get the list of most recent trades for a particular symbol
   * @see https://developers.bydfi.com/en/futures/market#recent-trades
   * @param {string} symbol unified symbol of the market to fetch trades for
   * @param {int} [since] timestamp in ms of the earliest trade to fetch
   * @param {int} [limit] the maximum amount of trades to fetch (default 500,
   * max 1000)
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.fromId] retrieve from which trade ID to start. Default
   * to retrieve the most recent trade records
   * @returns {Trade[]} a list of [trade structures]{@link
   * https://docs.ccxt.com/?id=public-trades}
   */
  std::shared_future<ccxt::any>
  fetchTrades(ccxt::any symbol, ccxt::any since = ccxt::any{},
              ccxt::any limit = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        ccxt::any market = this->market(symbol);
                        ccxt::any request = ccxt::dict{
                            {std::string("symbol"),
                             ::getValue(market, std::string("id"))},
                        };
                        if (isTrue(!isEqual(limit, ccxt::any{}))) {
                          ::setValue(request, std::string("limit"),
                                     mathMin(limit, 1000));
                        }
                        ccxt::any response =
                            awaitValue(this->publicGetV1FapiMarketTrades(
                                this->extend(request, params)));
                        //
                        //     {
                        //         "code": 200,
                        //         "message": "success",
                        //         "data": [
                        //             {
                        //                 "id": "7407825178362667008",
                        //                 "symbol": "ETH-USDT",
                        //                 "price": "2970.49",
                        //                 "quantity": "63",
                        //                 "side": "SELL",
                        //                 "time": 1766163153218
                        //             }
                        //         ],
                        //         "success": true
                        //     }
                        //
                        ccxt::any data = this->safeList(
                            response, std::string("data"), ccxt::list{});
                        return this->parseTrades(data, market, since, limit);
                      })
        .share();
  }

  /**
   * @method
   * @name bydfi#fetchMyTrades
   * @description fetch all trades made by the user
   * @see https://developers.bydfi.com/en/futures/trade#historical-trades-query
   * @param {string} symbol unified market symbol
   * @param {int} [since] the earliest time in ms to fetch trades for
   * @param {int} [limit] the maximum number of trades structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] the latest time in ms to fetch trades for
   * @param {string} [params.contractType] FUTURE or DELIVERY, default is FUTURE
   * @param {string} [params.wallet] The unique code of a sub-wallet
   * @param {string} [params.orderType] order type ('LIMIT', 'MARKET', 'LIQ',
   * 'LIMIT_CLOSE', 'MARKET_CLOSE', 'STOP', 'TAKE_PROFIT', 'STOP_MARKET',
   * 'TAKE_PROFIT_MARKET' or 'TRAILING_STOP_MARKET')
   * @returns {Trade[]} a list of [trade structures]{@link
   * https://docs.ccxt.com/?id=trade-structure}
   */
  std::shared_future<ccxt::any>
  fetchMyTrades(ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
                ccxt::any limit = ccxt::any{},
                ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any paginate =
                     this->safeBool(params, std::string("paginate"), false);
                 if (isTrue(isEqual(paginate, true))) {
                   ccxt::any maxLimit = 500;
                   params = this->omit(params, std::string("paginate"));
                   params = this->extend(
                       params, ccxt::dict{
                                   {std::string("paginationDirection"),
                                    std::string("backward")},
                               });
                   ccxt::any paginatedResponse =
                       awaitValue(this->fetchPaginatedCallDynamic(
                           std::string("fetchMyTrades"), symbol, since, limit,
                           params, maxLimit, true));
                   return this->sortBy(paginatedResponse,
                                       std::string("timestamp"));
                 }
                 ccxt::any contractType = std::string("FUTURE");
                 ccxt::any contractTypeparamsVariable =
                     this->handleOptionAndParams(
                         params, std::string("fetchMyTrades"),
                         std::string("contractType"), contractType);
                 contractType = ::getValue(contractTypeparamsVariable, 0);
                 params = ::getValue(contractTypeparamsVariable, 1);
                 ccxt::any request = ccxt::dict{
                     {std::string("contractType"), contractType},
                 };
                 ccxt::any market = ccxt::any{};
                 if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                   market = this->market(symbol);
                   ::setValue(request, std::string("symbol"),
                              ::getValue(market, std::string("id")));
                 }
                 params = this->handleSinceAndUntil(
                     std::string("fetchMyTrades"), since, params);
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("limit"), limit);
                 }
                 ccxt::any response =
                     awaitValue(this->privateGetV1FapiTradeHistoryTrade(
                         this->extend(request, params)));
                 //
                 //     {
                 //         "code": 200,
                 //         "message": "success",
                 //         "data": [
                 //             {
                 //                 "orderId": "7408919189505597440",
                 //                 "wallet": "W001",
                 //                 "symbol": "ETH-USDC",
                 //                 "time": "1766423985842",
                 //                 "dealPrice": "3032.45",
                 //                 "dealVolume": "1",
                 //                 "fee": "0",
                 //                 "side": "BUY",
                 //                 "type": "2",
                 //                 "liqPrice": null,
                 //                 "basePrecision": "8",
                 //                 "baseShowPrecision": "2",
                 //                 "tradePnl": "0",
                 //                 "marginType": "CROSS",
                 //                 "leverageLevel": 1
                 //             }
                 //         ],
                 //         "success": true
                 //     }
                 //
                 ccxt::any data = this->safeList(response, std::string("data"),
                                                 ccxt::list{});
                 return this->parseTrades(data, market, since, limit);
               })
        .share();
  }

  ccxt::any parseTrade(ccxt::any trade,
                       ccxt::any market = ccxt::any{}) override {
    //
    // fetchTrades
    //     {
    //         "id": "7407825178362667008",
    //         "symbol": "ETH-USDT",
    //         "price": "2970.49",
    //         "quantity": "63",
    //         "side": "SELL",
    //         "time": 1766163153218
    //     }
    //
    // fetchMyTrades
    //     {
    //         "orderId": "7408919189505597440",
    //         "wallet": "W001",
    //         "symbol": "ETH-USDC",
    //         "time": "1766423985842",
    //         "dealPrice": "3032.45",
    //         "dealVolume": "1",
    //         "fee": "0",
    //         "side": "BUY",
    //         "type": "2",
    //         "liqPrice": null,
    //         "basePrecision": "8",
    //         "baseShowPrecision": "2",
    //         "tradePnl": "0",
    //         "marginType": "CROSS",
    //         "leverageLevel": 1
    //     }
    //
    ccxt::any marketId = this->safeString(trade, std::string("symbol"));
    market = this->safeMarket(marketId, market);
    ccxt::any timestamp = this->safeInteger(trade, std::string("time"));
    ccxt::any fee = ccxt::any{};
    ccxt::any rawType = this->safeString(trade, std::string("type"));
    ccxt::any feeCost = this->safeString(trade, std::string("fee"));
    if (isTrue(!isEqual(feeCost, ccxt::any{}))) {
      fee = ccxt::dict{
          {std::string("cost"), feeCost},
          {std::string("currency"), ::getValue(market, std::string("settle"))},
      };
    }
    ccxt::any orderId = this->safeString(trade, std::string("orderId"));
    ccxt::any side = ccxt::any{}; // fetchMyTrades always returns side BUY
    if (isTrue(isEqual(orderId, ccxt::any{}))) {
      // from fetchTrades
      side = this->safeStringLower(trade, std::string("side"));
    }
    return this->safeTrade(
        ccxt::dict{
            {std::string("info"), trade},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("symbol"), ::getValue(market, std::string("symbol"))},
            {std::string("id"), this->safeString(trade, std::string("id"))},
            {std::string("order"), orderId},
            {std::string("type"), this->parseTradeType(rawType)},
            {std::string("side"), side},
            {std::string("takerOrMaker"), ccxt::any{}},
            {std::string("price"),
             this->safeString2(trade, std::string("price"),
                               std::string("dealPrice"))},
            {std::string("amount"),
             this->safeString2(trade, std::string("quantity"),
                               std::string("dealVolume"))},
            {std::string("cost"), ccxt::any{}},
            {std::string("fee"), fee},
        },
        market);
  }

  virtual ccxt::any parseTradeType(ccxt::any type) {
    ccxt::any types = ccxt::dict{
        {std::string("1"), std::string("limit")},
        {std::string("2"), std::string("market")},
        {std::string("3"), std::string("liquidation")},
    };
    return this->safeString(types, type, type);
  }

  /**
   * @method
   * @name bydfi#fetchOHLCV
   * @description fetches historical candlestick data containing the open, high,
   * low, and close price, and the volume of a market
   * @see https://developers.bydfi.com/en/futures/market#candlestick-data
   * @param {string} symbol unified symbol of the market to fetch OHLCV data for
   * @param {string} timeframe the length of time each candle represents
   * @param {int} [since] timestamp in ms of the earliest candle to fetch
   * @param {int} [limit] the maximum amount of candles to fetch (max 500)
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] timestamp in ms of the latest candle to fetch
   * @returns {int[][]} A list of candles ordered as timestamp, open, high, low,
   * close, volume
   */
  std::shared_future<ccxt::any>
  fetchOHLCV(ccxt::any symbol, ccxt::any timeframe = std::string("1m"),
             ccxt::any since = ccxt::any{}, ccxt::any limit = ccxt::any{},
             ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any maxLimit =
                     500; // docs says max 1500, but in practice only 500 works
                 ccxt::any paginate = false;
                 ccxt::any paginateparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchOHLCV"),
                     std::string("paginate"));
                 paginate = ::getValue(paginateparamsVariable, 0);
                 params = ::getValue(paginateparamsVariable, 1);
                 if (isTrue(paginate)) {
                   return this->fetchPaginatedCallDeterministic(
                       std::string("fetchOHLCV"), symbol, since, limit,
                       timeframe, params, maxLimit);
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any interval =
                     this->safeString(this->timeframes, timeframe, timeframe);
                 ccxt::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                     {std::string("interval"), interval},
                 };
                 ccxt::any startTime = since;
                 ccxt::any numberOfCandles =
                     (isTrue((isTrue(isTrue(!isEqual(limit, ccxt::any{})) &&
                                     isTrue(!isEqual(limit, null))) &&
                              isTrue(!isEqual(limit, 0))))
                          ? ccxt::any(limit)
                          : ccxt::any(maxLimit));
                 ccxt::any until = ccxt::any{};
                 ccxt::any untilparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchOHLCV"), std::string("until"));
                 until = ::getValue(untilparamsVariable, 0);
                 params = ::getValue(untilparamsVariable, 1);
                 ccxt::any now = this->milliseconds();
                 ccxt::any duration =
                     multiply(this->parseTimeframe(timeframe), 1000);
                 ccxt::any timeDelta = multiply(duration, numberOfCandles);
                 if (isTrue(isTrue(isEqual(startTime, ccxt::any{})) &&
                            isTrue(isEqual(until, ccxt::any{})))) {
                   startTime = subtract(now, timeDelta);
                   until = now;
                 } else if (isTrue(isEqual(until, ccxt::any{}))) {
                   if (isTrue(isEqual(startTime, ccxt::any{}))) {
                     throw ArgumentsRequired(toString(add(
                         this->id, std::string(" fetchOHLCV() requires a since "
                                               "or until argument"))));
                   }
                   until = add(startTime, timeDelta);
                   if (isTrue(isGreaterThan(until, now))) {
                     until = now;
                   }
                 } else if (isTrue(isEqual(startTime, ccxt::any{}))) {
                   startTime = subtract(until, timeDelta);
                 }
                 ::setValue(request, std::string("startTime"), startTime);
                 ::setValue(request, std::string("endTime"), until);
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("limit"), limit);
                 }
                 ccxt::any response =
                     awaitValue(this->publicGetV1FapiMarketKlines(
                         this->extend(request, params)));
                 //
                 //     {
                 //         "code": 200,
                 //         "message": "success",
                 //         "data": [
                 //             {
                 //                 "s": "ETH-USDT",
                 //                 "t": "1766166000000",
                 //                 "c": "2964.990000000000000000",
                 //                 "o": "2967.830000000000000000",
                 //                 "h": "2967.830000000000000000",
                 //                 "l": "2964.130000000000000000",
                 //                 "v": "20358.000000000000000000"
                 //             }
                 //         ],
                 //         "success": true
                 //     }
                 //
                 ccxt::any data = this->safeList(response, std::string("data"),
                                                 ccxt::list{});
                 ccxt::any result =
                     this->parseOHLCVs(data, market, timeframe, since, limit);
                 return result;
               })
        .share();
  }

  ccxt::any parseOHLCV(ccxt::any ohlcv,
                       ccxt::any market = ccxt::any{}) override {
    //
    //     {
    //         "s": "ETH-USDT",
    //         "t": "1766166000000",
    //         "c": "2964.990000000000000000",
    //         "o": "2967.830000000000000000",
    //         "h": "2967.830000000000000000",
    //         "l": "2964.130000000000000000",
    //         "v": "20358.000000000000000000"
    //     }
    //
    return ccxt::list{this->safeInteger(ohlcv, std::string("t")),
                      this->safeNumber(ohlcv, std::string("o")),
                      this->safeNumber(ohlcv, std::string("h")),
                      this->safeNumber(ohlcv, std::string("l")),
                      this->safeNumber(ohlcv, std::string("c")),
                      this->safeNumber(ohlcv, std::string("v"))};
  }

  /**
   * @method
   * @name bydfi#fetchTickers
   * @see
   * https://developers.bydfi.com/en/futures/market#24hr-price-change-statistics
   * @description fetches price tickers for multiple markets, statistical
   * information calculated over the past 24 hours for each market
   * @param {string[]|undefined} symbols unified symbols of the markets to fetch
   * the ticker for, all market tickers are returned if not assigned
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a dictionary of [ticker structures]{@link
   * https://docs.ccxt.com/?id=ticker-structure}
   */
  std::shared_future<ccxt::any>
  fetchTickers(ccxt::any symbols = ccxt::any{},
               ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        ccxt::any response = awaitValue(
                            this->publicGetV1FapiMarketTicker24hr(params));
                        //
                        //     {
                        //         "code": 200,
                        //         "message": "success",
                        //         "data": [
                        //             {
                        //                 "symbol": "BTC-USDT",
                        //                 "open": "86452.9",
                        //                 "high": "89371.2",
                        //                 "low": "84418.5",
                        //                 "last": "87050.3",
                        //                 "vol": "12938783",
                        //                 "time": 1766169423872
                        //             }
                        //         ],
                        //         "success": true
                        //     }
                        //
                        ccxt::any data = this->safeList(
                            response, std::string("data"), ccxt::list{});
                        return this->parseTickers(data, symbols);
                      })
        .share();
  }

  /**
   * @method
   * @name bydfi#fetchTicker
   * @description fetches a price ticker, a statistical calculation with the
   * information calculated over the past 24 hours for a specific market
   * @see
   * https://developers.bydfi.com/en/futures/market#24hr-price-change-statistics
   * @param {string} symbol unified symbol of the market to fetch the ticker for
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [ticker structure]{@link
   * https://docs.ccxt.com/?id=ticker-structure}
   */
  std::shared_future<ccxt::any>
  fetchTicker(ccxt::any symbol, ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        ccxt::any market = this->market(symbol);
                        ccxt::any request = ccxt::dict{
                            {std::string("symbol"),
                             ::getValue(market, std::string("id"))},
                        };
                        ccxt::any response =
                            awaitValue(this->publicGetV1FapiMarketTicker24hr(
                                this->extend(request, params)));
                        ccxt::any data = this->safeList(
                            response, std::string("data"), ccxt::list{});
                        ccxt::any ticker =
                            this->safeDict(data, 0, ccxt::dict{});
                        return this->parseTicker(ticker, market);
                      })
        .share();
  }

  ccxt::any parseTicker(ccxt::any ticker,
                        ccxt::any market = ccxt::any{}) override {
    //
    // fetchTicker/fetchTickers
    //     {
    //         "symbol": "BTC-USDT",
    //         "open": "86452.9",
    //         "high": "89371.2",
    //         "low": "84418.5",
    //         "last": "87050.3",
    //         "vol": "12938783",
    //         "time": 1766169423872
    //     }
    //
    ccxt::any marketId =
        this->safeString2(ticker, std::string("symbol"), std::string("s"));
    market = this->safeMarket(marketId, market);
    ccxt::any timestamp =
        this->safeInteger2(ticker, std::string("time"), std::string("E"));
    ccxt::any last =
        this->safeString2(ticker, std::string("last"), std::string("c"));
    return this->safeTicker(
        ccxt::dict{
            {std::string("symbol"), this->safeSymbol(marketId, market)},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("high"),
             this->safeString2(ticker, std::string("high"), std::string("h"))},
            {std::string("low"),
             this->safeString2(ticker, std::string("low"), std::string("l"))},
            {std::string("bid"), ccxt::any{}},
            {std::string("bidVolume"), ccxt::any{}},
            {std::string("ask"), ccxt::any{}},
            {std::string("askVolume"), ccxt::any{}},
            {std::string("vwap"), ccxt::any{}},
            {std::string("open"),
             this->safeString2(ticker, std::string("open"), std::string("o"))},
            {std::string("close"), last},
            {std::string("last"), last},
            {std::string("previousClose"), ccxt::any{}},
            {std::string("change"), ccxt::any{}},
            {std::string("percentage"), ccxt::any{}},
            {std::string("average"), ccxt::any{}},
            {std::string("baseVolume"),
             this->safeString2(ticker, std::string("vol"), std::string("v"))},
            {std::string("quoteVolume"), ccxt::any{}},
            {std::string("markPrice"), ccxt::any{}},
            {std::string("indexPrice"), ccxt::any{}},
            {std::string("info"), ticker},
        },
        market);
  }

